-- Vanilla dungeon baseline: Normal / Heroic / Mythic (MapDifficulty.dbc modes 0 / 1 / 2).
-- Creature variants: Exiles creature names, export 2026-09-13; only attested families are copied.
-- PROVISIONAL: variants retain the existing Normal combat values, AI, loot pools and drop chances.
-- Existing event scripts, pools, paths and spawn coordinates are retained, including summoned bosses.
-- The Exiles aggregated creature drop list is NOT a server loot table and is not imported.
-- Item lineage: AtlasLoot_Cache plus name/class/subclass/slot matches to @Heroic Dungeon@ / @Mythic Dungeon@.
-- Legacy @Mythic@ labels require an explicit AtlasLoot mapping, RequiredLevel 60 and ItemLevel >= 60.
-- Missing or conflicting variants are left unmapped; Mythic+ items are excluded.

CREATE TABLE IF NOT EXISTS `coa_dungeon_loot_variant` (
  `base_item` INT UNSIGNED NOT NULL,
  `heroic_item` INT UNSIGNED NOT NULL DEFAULT 0,
  `mythic_item` INT UNSIGNED NOT NULL DEFAULT 0,
  PRIMARY KEY (`base_item`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

