-- Include the existing spawns in both additional difficulties without duplicating their GUIDs.
UPDATE `creature` SET `spawnMask` = `spawnMask` | 6 WHERE (`spawnMask` & 1) <> 0 AND `map` IN (33,34,36,43,47,48,70,90,109,129,189,209,229,230,289,329,349,389,429);
UPDATE `gameobject` SET `spawnMask` = `spawnMask` | 6 WHERE (`spawnMask` & 1) <> 0 AND `map` IN (33,34,36,43,47,48,70,90,109,129,189,209,229,230,289,329,349,389,429);

-- Higher difficulties inherit the same entry requirements as Normal for this baseline.
-- Existing custom access rows are preserved; no new attunements or minimum item levels are inferred.
DELETE FROM `dungeon_access_template` WHERE `id` = 0 AND `map_id` = 0;
INSERT INTO `dungeon_access_template` (`map_id`, `difficulty`, `min_level`, `max_level`, `min_avg_item_level`, `comment`)
SELECT `normal`.`map_id`, 1, `normal`.`min_level`, `normal`.`max_level`, `normal`.`min_avg_item_level`,
    CONCAT(`normal`.`comment`, ' - Heroic (provisional Normal access)')
FROM `dungeon_access_template` AS `normal`
LEFT JOIN `dungeon_access_template` AS `existing`
    ON `existing`.`map_id` = `normal`.`map_id` AND `existing`.`difficulty` = 1
WHERE `normal`.`difficulty` = 0 AND `existing`.`id` IS NULL
    AND `normal`.`map_id` IN (33,34,36,43,47,48,70,90,109,129,189,209,229,230,289,329,349,389,429);
DELETE FROM `dungeon_access_template` WHERE `id` = 0 AND `map_id` = 0;
INSERT INTO `dungeon_access_template` (`map_id`, `difficulty`, `min_level`, `max_level`, `min_avg_item_level`, `comment`)
SELECT `normal`.`map_id`, 2, `normal`.`min_level`, `normal`.`max_level`, `normal`.`min_avg_item_level`,
    CONCAT(`normal`.`comment`, ' - Mythic (provisional Normal access)')
FROM `dungeon_access_template` AS `normal`
LEFT JOIN `dungeon_access_template` AS `existing`
    ON `existing`.`map_id` = `normal`.`map_id` AND `existing`.`difficulty` = 2
WHERE `normal`.`difficulty` = 0 AND `existing`.`id` IS NULL
    AND `normal`.`map_id` IN (33,34,36,43,47,48,70,90,109,129,189,209,229,230,289,329,349,389,429);
